import { cac } from './src/index.ts';

// Test 1: Parsing --base-url should set both baseUrl and b to parsed value
const cli1 = cac();
cli1.option('-b, --base-url <url>', 'Set the URL', { default: 'https://github.com' });
const { options: opts1 } = cli1.parse(['node', 'bin', '--base-url', 'https://gitlab.com']);
console.assert(opts1.baseUrl === 'https://gitlab.com', 'baseUrl should be parsed value');
console.assert(opts1.b === 'https://gitlab.com', 'b should sync to parsed value');
console.log('Test 1 PASSED: --base-url parsed, both aliases set correctly');

// Test 2: No args should use defaults for all aliases
const cli2 = cac();
cli2.option('-b, --base-url <url>', 'Set the URL', { default: 'https://github.com' });
const { options: opts2 } = cli2.parse(['node', 'bin']);
console.assert(opts2.baseUrl === 'https://github.com', 'baseUrl should be default');
console.assert(opts2.b === 'https://github.com', 'b should be default');
console.log('Test 2 PASSED: no args, defaults applied to all aliases');

// Test 3: Parsing -b should set both b and baseUrl to parsed value
const cli3 = cac();
cli3.option('-b, --base-url <url>', 'Set the URL', { default: 'https://github.com' });
const { options: opts3 } = cli3.parse(['node', 'bin', '-b', 'https://gitlab.com']);
console.assert(opts3.b === 'https://gitlab.com', 'b should be parsed value');
console.assert(opts3.baseUrl === 'https://gitlab.com', 'baseUrl should sync to parsed value');
console.log('Test 3 PASSED: -b parsed, both aliases set correctly');

console.log('All tests PASSED!');
" 2>&1

